function OnPlayerPossessed()
{
    Log("Player possessed - Director detected new player");

    if (PlayerHarry != None)
    {
        PlayerHarry.EnablePlayerInput();
        PlayerHarry.bKeepStationary = False;
        PlayerHarry.bIsCaptured = False;
        PlayerHarry.bAllowHarryToDie = False;

        PlayerHarry.GotoState('PlayerWalking');
        PlayerHarry.SetPhysics(PHYS_Walking);
        PlayerHarry.bIsPlayer = True;
        PlayerHarry.bHidden = False;
        PlayerHarry.Health = 100;

        PlayerHarry.ClientSetRotation(PlayerHarry.Rotation);
        PlayerHarry.ViewRotation = PlayerHarry.Rotation;

        if (PlayerHarry.Cam != None)
        {
            PlayerHarry.Cam.SetCameraMode(3); // CM_Standard
            PlayerHarry.Cam.InitTarget(PlayerHarry);
            PlayerHarry.Cam.InitPositionAndRotation(True);
            Log("=== Director forced Standard Camera for new player ===");
        }

        Console = baseConsole(PlayerHarry.Player.Console);
    }
}

